/* ── Reset & Variables ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #0f111a;
  --sidebar-bg: #161822;
  --card: #1e2030;
  --bubble-me: #3b5bdb;
  --bubble-them: #1e2030;
  --accent: #7c5cfc;
  --text: #e4e6f0;
  --text-muted: #8b8fa3;
  --border: #2a2d3e;
  --green: #3ddc84;
  --yellow: #f5c542;
  --red: #ff6b6b;
  --radius: 12px;
  --transition: .2s ease;
}

html, body { height: 100%; }

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
}

/* ── Layout ── */
.app {
  display: flex;
  width: 100%;
  max-width: 1200px;
  height: 100vh;
  max-height: 800px;
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 0 8px 32px rgba(0,0,0,.4);
}

/* ── Sidebar ── */
.sidebar {
  width: 280px;
  min-width: 280px;
  background: var(--sidebar-bg);
  display: flex;
  flex-direction: column;
  border-right: 1px solid var(--border);
}

.sidebar-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px;
  border-bottom: 1px solid var(--border);
}

.sidebar-header h2 { font-size: 1.1rem; }

.icon-btn {
  background: none;
  border: none;
  color: var(--text-muted);
  cursor: pointer;
  font-size: 1.1rem;
  padding: 4px 8px;
  border-radius: 6px;
  transition: var(--transition);
}
.icon-btn:hover { background: var(--border); color: var(--text); }

.search-bar { padding: 8px 16px; }
.search-bar input {
  width: 100%;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--card);
  color: var(--text);
  font-size: .85rem;
  outline: none;
  transition: var(--transition);
}
.search-bar input:focus { border-color: var(--accent); }

.channel-list {
  flex: 1;
  overflow-y: auto;
  list-style: none;
}

.channel-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  cursor: pointer;
  transition: var(--transition);
  position: relative;
}
.channel-item:hover { background: var(--card); }
.channel-item.active { background: var(--card); border-left: 3px solid var(--accent); }

.channel-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .85rem;
  font-weight: 700;
  flex-shrink: 0;
  position: relative;
}
.channel-avatar .status-dot {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 2px solid var(--sidebar-bg);
}

.status-dot.online { background: var(--green); }
.status-dot.away { background: var(--yellow); }
.status-dot.offline { background: #555; }

.channel-meta { flex: 1; min-width: 0; }
.channel-meta .name { font-size: .9rem; font-weight: 600; }
.channel-meta .preview {
  font-size: .78rem;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.channel-time {
  font-size: .7rem;
  color: var(--text-muted);
  flex-shrink: 0;
}

.unread-badge {
  background: var(--accent);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  border-radius: 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  flex-shrink: 0;
}

.user-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  border-top: 1px solid var(--border);
}
.user-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: .8rem;
  font-weight: 700;
  background: var(--accent);
  color: #fff;
}
.user-name { flex: 1; font-size: .85rem; font-weight: 600; }

/* ── Chat Area ── */
.chat-area {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--bg);
  position: relative;
}

.chat-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 20px;
  border-bottom: 1px solid var(--border);
  background: var(--sidebar-bg);
}
.channel-info h3 { font-size: 1rem; }
.member-count { font-size: .75rem; color: var(--text-muted); }

/* ── Typing Indicator ── */
.typing-indicator {
  font-size: .8rem;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 20px;
}
.typing-dots {
  display: inline-flex;
  gap: 3px;
  margin-right: 4px;
}
.typing-dots span {
  width: 5px;
  height: 5px;
  background: var(--text-muted);
  border-radius: 50%;
  animation: bounce 1.4s infinite;
}
.typing-dots span:nth-child(2) { animation-delay: .2s; }
.typing-dots span:nth-child(3) { animation-delay: .4s; }

@keyframes bounce {
  0%, 60%, 100% { transform: translateY(0); }
  30% { transform: translateY(-4px); }
}

/* ── Messages ── */
.messages {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.message {
  display: flex;
  flex-direction: column;
  max-width: 70%;
  animation: fadeIn .25s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

.message.me { align-self: flex-end; }
.message.them { align-self: flex-start; }

.message .sender {
  font-size: .72rem;
  color: var(--text-muted);
  margin-bottom: 3px;
  padding: 0 4px;
}
.message.me .sender { text-align: right; }

.bubble {
  padding: 10px 14px;
  border-radius: 18px;
  font-size: .9rem;
  line-height: 1.45;
  word-break: break-word;
  position: relative;
}

.message.me .bubble {
  background: var(--bubble-me);
  color: #fff;
  border-bottom-right-radius: 4px;
}

.message.them .bubble {
  background: var(--bubble-them);
  border: 1px solid var(--border);
  border-bottom-left-radius: 4px;
}

.message .time {
  font-size: .65rem;
  color: var(--text-muted);
  margin-top: 3px;
  padding: 0 4px;
}
.message.me .time { text-align: right; }

.system-msg {
  align-self: center;
  font-size: .75rem;
  color: var(--text-muted);
  background: var(--card);
  padding: 4px 12px;
  border-radius: 10px;
  margin: 8px 0;
