.send-btn:hover { background: #5a3fd6; transform: scale(1.05); }

/* ── Emoji Picker ── */
.emoji-picker {
  position: absolute;
  bottom: 70px;
  left: 16px;
  width: 320px;
  max-height: 360px;
  background: var(--sidebar-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
