.cat-btn:hover, .cat-btn.active { background: var(--card); }

.emoji-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 2px;
  padding: 8px;
  overflow-y: auto;
  flex: 1;
}

.emoji-grid button {
  background: none;
