    const li = document.createElement('li');
    li.className = `channel-item${ch.id === activeChannel ? ' active' : ''}`;

    const avatarColor = ch.type === 'dm' ? USERS[ch.members[0]]?.color : USERS.team.color;
    const avatarText = ch.type === 'dm' ? (USERS[ch.members[0]]?.name || '?')[0] : '#';
    const status = ch.type === 'dm' ? USERS[ch.members[0]]?.status || 'offline' : '';

    const { preview, time } = getLastMessage(ch);

    li.innerHTML = `
      <div class="channel-avatar" style="background:${avatarColor};color:#fff">
        ${avatarText}
        ${status ? `<div class="status-dot ${status}"></div>` : ''}
      </div>
      <div class="channel-meta">
        <div class="name">${ch.name}</div>
        <div class="preview">${preview}</div>
      </div>
      <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px">
        <span class="channel-time">${time ? formatChannelTime(time) : ''}</span>
        ${ch.unread ? `<span class="unread-badge">${ch.unread}</span>` : ''}
      </div>
    `;
    li.addEventListener('click', () => openChannel(ch.id));
    channelListEl.appendChild(li);
  });
}

// ── Open Channel ──
function openChannel(id) {
  activeChannel = id;
  const ch = channels.find(c => c.id === id);
  if (!ch) return;
  ch.unread = 0;

  channelNameEl.textContent = ch.type === 'group' ? `# ${ch.name}` : ch.name;
  const memberNames = ch.members.map(m => USERS[m]?.name).filter(Boolean).join(', ');
  memberCountEl.textContent = ch.type === 'group' ? `${ch.members.length + 1} members` : `${memberNames} · ${USERS[ch.members[0]]?.status || 'offline'}`;

  renderChannels(searchInput.value);
  renderMessages();
  messageInput.focus();
}

// ── Render Messages ──
function renderMessages() {
  messagesEl.innerHTML = '';
  const ch = channels.find(c => c.id === activeChannel);
  if (!ch) {
    messagesEl.innerHTML = '<div class="empty-state"><div class="icon">💬</div><p>Select a conversation to start chatting</p></div>';
    return;
  }

  ch.messages.forEach(msg => {
    if (msg.system) {
      const div = document.createElement('div');
      div.className = 'system-msg';
      div.textContent = msg.text;
      messagesEl.appendChild(div);
      return;
    }

    const div = document.createElement('div');
    div.className = `message ${msg.sender === 'me' ? 'me' : 'them'}`;

    const senderName = msg.sender === 'me' ? '' : (USERS[msg.sender]?.name || msg.sender);
    div.innerHTML = `
      ${senderName && ch.type === 'group' ? `<span class="sender" style="color:${USERS[msg.sender]?.color}">${senderName}</span>` : ''}
      <div class="bubble">${escapeHtml(msg.text)}</div>
      <span class="time">${formatTime(msg.time)}</span>
    `;
    messagesEl.appendChild(div);
  });

  messagesEl.scrollTop = messagesEl.scrollHeight;
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

// ── Send Message ──
function sendMessage() {
  const text = messageInput.value.trim();
  if (!text || !activeChannel) return;

  const ch = channels.find(c => c.id === activeChannel);
  if (!ch) return;

  ch.messages.push({ id: ++msgIdCounter, sender: 'me', text, time: Date.now() });
  messageInput.value = '';
  renderMessages();
  renderChannels(searchInput.value);

  // Simulate reply
  simulateReply(ch);
}

function simulateReply(ch) {
  if (ch.type === 'dm' && USERS[ch.members[0]]?.status === 'offline') return;

  const replier = ch.members[Math.floor(Math.random() * ch.members.length)];
  const user = USERS[replier];
  if (!user) return;

  // Show typing
  const typingTimeout = 1500 + Math.random() * 2000;
  typingEl.innerHTML = `<span class="typing-dots"><span></span><span></span><span></span></span> ${user.name} is typing…`;

  setTimeout(() => {
    typingEl.innerHTML = '';
    if (activeChannel !== ch.id) {
      ch.unread = (ch.unread || 0) + 1;
    }

    ch.messages.push({
      id: ++msgIdCounter,
      sender: replier,
      text: AUTO_REPLIES[Math.floor(Math.random() * AUTO_REPLIES.length)],
      time: Date.now(),
    });

    renderMessages();
    renderChannels(searchInput.value);
  }, typingTimeout);
}

// ── Emoji Picker ──
function buildEmojiPicker() {
  emojiCategories.innerHTML = '';
  emojiGrid.innerHTML = '';

  const keys = Object.keys(EMOJIS);
  keys.forEach((cat, i) => {
    const btn = document.createElement('button');
    btn.className = `cat-btn${i === 0 ? ' active' : ''}`;
    btn.textContent = cat;
    btn.addEventListener('click', () => {
      emojiCategories.querySelectorAll('.cat-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      renderEmojiGrid(EMOJIS[cat]);
    });
    emojiCategories.appendChild(btn);
  });

  renderEmojiGrid(EMOJIS[keys[0]]);
}

function renderEmojiGrid(emojis) {
  emojiGrid.innerHTML = '';
  emojis.forEach(e => {
    const btn = document.createElement('button');
    btn.textContent = e;
    btn.addEventListener('click', () => {
      messageInput.value += e;
      messageInput.focus();
    });
    emojiGrid.appendChild(btn);
  });
}

// ── New Channel Modal ──
function createNewChannelModal() {
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.innerHTML = `
    <div class="modal">
      <h3>New Channel</h3>
      <input type="text" id="newChannelName" placeholder="Channel name…" autocomplete="off">
      <div class="modal-actions">
        <button class="btn-cancel" id="modalCancel">Cancel</button>
        <button class="btn-primary" id="modalCreate">Create</button>
      </div>
    </div>
  `;

  const input = overlay.querySelector('#newChannelName');
  setTimeout(() => input.focus(), 50);

  function create() {
    const name = input.value.trim();
    if (!name) return;
    const id = name.toLowerCase().replace(/\s+/g, '-') + '-' + Date.now();
    const shuffled = Object.keys(USERS).filter(u => u !== 'team').sort(() => Math.random() - .5).slice(0, 3);
    channels.unshift({
      id,
      name,
      type: 'group',
      members: shuffled,
      messages: [],
      unread: 0,
    });
    overlay.remove();
    renderChannels();
    openChannel(id);
  }

  overlay.querySelector('#modalCancel').addEventListener('click', () => overlay.remove());
  overlay.querySelector('#modalCreate').addEventListener('click', create);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') create();
    if (e.key === 'Escape') overlay.remove();
  });
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) overlay.remove();
  });

  document.body.appendChild(overlay);
  overlay.classList.add('open');
}

// ── Event Listeners ──
sendBtn.addEventListener('click', sendMessage);
messageInput.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && !e.shiftKey) {
    e.preventDefault();
    sendMessage();
  }
});

emojiBtn.addEventListener('click', (e) => {
  e.stopPropagation();
  emojiPicker.classList.toggle('open');
});
closeEmojiBtn.addEventListener('click', () => emojiPicker.classList.remove('open'));
document.addEventListener('click', (e) => {
  if (!emojiPicker.contains(e.target) && e.target !== emojiBtn) {
    emojiPicker.classList.remove('open');
  }
});

searchInput.addEventListener('input', () => renderChannels(searchInput.value));
newChannelBtn.addEventListener('click', createNewChannelModal);

// ── Init ──
buildEmojiPicker();
renderChannels();
renderMessages();

// Simulate periodic status changes & incoming messages for realism
setInterval(() => {
  const statuses = ['online', 'away', 'offline'];
  const userIds = Object.keys(USERS).filter(u => u !== 'team');
  const randomUser = userIds[Math.floor(Math.random() * userIds.length];
  const newStatus = statuses[Math.floor(Math.random() * statuses.length)];
  USERS[randomUser].status = newStatus;
  renderChannels(searchInput.value);

  if (activeChannel) {
    const ch = channels.find(c => c.id === activeChannel);
    if (ch) {
      if (ch.type === 'dm') {
        const u = USERS[ch.members[0]];
        memberCountEl.textContent = `${u?.name} · ${u?.status || 'offline'}`;
      }
    }
  }
}, 15000);

// Random incoming message in a random channel
setInterval(() => {
  const ch = channels[Math.floor(Math.random() * channels.length)];
  if (ch.id === activeChannel) return; // Don't auto-send if user is watching
  const replier = ch.members[Math.floor(Math.random() * ch.members.length)];
  if (!USERS[replier]) return;
  ch.messages.push({
    id: ++msgIdCounter,
    sender: replier,
    text: AUTO_REPLIES[Math.floor(Math.random() * AUTO_REPLIES.length)],
    time: Date.now(),
  });
  ch.unread = (ch.unread || 0) + 1;
  renderChannels(searchInput.value);
}, 20000);
